// Scoped enums can be forward-declared directly
enum class ScopedStatus;

void processStatus(ScopedStatus s); // OK: size is known

// Definition can appear elsewhere (e.g., in a .cpp file)
enum class ScopedStatus { Good, Failed, InProgress };

// Unscoped enums require specifying the underlying type to be forward-declared
enum UnscopedColor : unsigned char; // Must specify underlying type

void processColor(UnscopedColor c); // OK: size is now known

// The definition must match the forward declaration's underlying type
enum UnscopedColor : unsigned char { Red, Green, Blue };

